import test from "node:test";
import assert from "node:assert/strict";
import { createCache } from "../src/cache.js";

test("coalesces concurrent misses for the same key", async () => {
  let resolveLoad;
  let calls = 0;
  const cache = createCache(() => { calls++; return new Promise((resolve) => { resolveLoad = resolve; }); }, { ttlMs: 10, now: () => 0 });
  const first = cache.get("a");
  const second = cache.get("a");
  await new Promise((resolve) => setImmediate(resolve));
  assert.equal(calls, 1);
  resolveLoad("value");
  assert.deepEqual(await Promise.all([first, second]), ["value", "value"]);
});

test("expires values and retries after loader rejection", async () => {
  let time = 0;
  let calls = 0;
  const cache = createCache(async () => { if (++calls === 1) throw Error("temporary"); return calls; }, { ttlMs: 5, now: () => time });
  await assert.rejects(cache.get("a"), /temporary/);
  assert.equal(await cache.get("a"), 2);
  assert.equal(await cache.get("a"), 2);
  time = 6;
  assert.equal(await cache.get("a"), 3);
});
